/*
 * Host tests for the backup file format (core/src/backup.c), milestone M6.
 *   - Argon2id: RFC 9106 section 5.3 vector (Monocypher with lanes, secret, ad) and raw vectors
 *     from argon2-cffi (the reference implementation)
 *   - files generated by an independent Python implementation (tools/gen_backup_vectors.py):
 *     sealed byte for byte identically, opened, inspected
 *   - attacks: every bit of the file flipped (with and without a recomputed checksum), demo flag
 *     flipped, wrong / mistyped passwords, truncation, hostile KDF settings, authentic files
 *     with invalid payloads
 */
#include <stdio.h>
#include <string.h>

#include "backup_vectors.h"
#include "chacha20poly1305/rfc7539.h"
#include "monocypher.h"
#include "sha2.h"
#include "wallet/backup.h"
#include "wallet/mnemonic.h"

static int *g_checks_p, *g_fail_p;
#define CHECK(cond, ...)                                       \
  do {                                                         \
    (*g_checks_p)++;                                           \
    if (!(cond)) {                                             \
      (*g_fail_p)++;                                           \
      printf("  FAIL [backup] %s:%d: ", __FILE__, __LINE__);   \
      printf(__VA_ARGS__);                                     \
      printf("\n");                                            \
    }                                                          \
  } while (0)
#define NV(a) (sizeof(a) / sizeof((a)[0]))

static uint8_t work[64 * 1024];

static void test_argon2_rfc9106(void) {
  /* RFC 9106 5.3: Argon2id, m = 32 KiB, t = 3, p = 4, with secret and associated data */
  uint8_t pass[32], salt[16], secret[8], ad[12], out[32];
  memset(pass, 1, 32), memset(salt, 2, 16), memset(secret, 3, 8), memset(ad, 4, 12);
  static const uint8_t want[32] = {0x0d, 0x64, 0x0d, 0xf5, 0x8d, 0x78, 0x76, 0x6c, 0x08, 0xc0, 0x37,
                                   0xa3, 0x4a, 0x8b, 0x53, 0xc9, 0xd0, 0x1e, 0xf0, 0x45, 0x2d, 0x75,
                                   0xb6, 0x5e, 0xb5, 0x25, 0x20, 0xe9, 0x6b, 0x01, 0xe6, 0x59};
  crypto_argon2_config cfg = {CRYPTO_ARGON2_ID, 32, 3, 4};
  crypto_argon2_inputs in = {pass, salt, 32, 16};
  crypto_argon2_extras ex = {secret, ad, 8, 12};
  crypto_argon2(out, 32, work, cfg, in, ex);
  CHECK(!memcmp(out, want, 32), "RFC 9106 Argon2id vector");
  for (size_t i = 0; i < NV(ARGON2_VECTORS); i++) {
    const argon2_vec_t *v = &ARGON2_VECTORS[i];
    crypto_argon2_config c = {CRYPTO_ARGON2_ID, v->m_kib, v->passes, 1};
    crypto_argon2_inputs n = {v->pass, v->salt, 16, 16};
    crypto_argon2(out, 32, work, c, n, crypto_argon2_no_extras);
    CHECK(!memcmp(out, v->out, 32), "argon2-cffi vector %zu (m=%u t=%u)", i, (unsigned)v->m_kib, (unsigned)v->passes);
  }
}

static wl_backup_payload_t payload_of(const backup_vec_t *v) {
  wl_backup_payload_t p;
  memset(&p, 0, sizeof(p));
  p.words = v->words;
  memcpy(p.idx, v->idx, sizeof(p.idx));
  p.blind_signing = v->blind;
  return p;
}

static bool same_payload(const wl_backup_payload_t *a, const wl_backup_payload_t *b) {
  return a->words == b->words && a->blind_signing == b->blind_signing && !memcmp(a->idx, b->idx, sizeof(a->idx));
}

static void fix_check(uint8_t *f) {
  uint8_t h[32];
  sha256_Raw(f, 132, h);
  memcpy(f + 132, h, 8);
}

static void test_vectors(void) {
  for (size_t i = 0; i < NV(BACKUP_VECTORS); i++) {
    const backup_vec_t *v = &BACKUP_VECTORS[i];
    wl_backup_payload_t p = payload_of(v), got;
    wl_kdf_t kdf = {v->m_kib, v->passes};
    uint8_t f[WL_BACKUP_FILE_LEN];
    CHECK(wl_backup_seal(&p, v->pw, v->demo, kdf, v->salt, v->nonce, work, sizeof(work), f) == WL_OK, "seal %zu", i);
    CHECK(!memcmp(f, v->file, sizeof(f)), "seal %zu matches the Python implementation byte for byte", i);
    bool wiped = true;
    for (size_t k = 0; k < v->m_kib * 1024u; k++) wiped &= work[k] == 0;
    CHECK(wiped, "work area wiped after seal %zu", i);
    wl_backup_info_t info;
    CHECK(wl_backup_inspect(v->file, sizeof(v->file), &info) == WL_OK, "inspect %zu", i);
    CHECK(info.demo == v->demo && info.kdf.m_kib == v->m_kib && info.kdf.passes == v->passes, "info %zu", i);
    CHECK(wl_backup_open(v->file, sizeof(v->file), v->pw, work, sizeof(work), &got) == WL_OK, "open %zu", i);
    CHECK(same_payload(&got, &p), "payload %zu round-trips", i);
  }
}

static void test_passwords(void) {
  const backup_vec_t *v = &BACKUP_VECTORS[2]; /* fast KDF settings */
  wl_backup_payload_t got;
  uint16_t pw[12];
  /* another valid password (different entropy, valid checksum) */
  uint8_t ent[16] = {9, 9, 9};
  size_t n;
  wl_mnemonic_from_entropy(ent, 16, pw, &n);
  CHECK(wl_backup_open(v->file, sizeof(v->file), pw, work, sizeof(work), &got) == WL_ERR_AUTH, "wrong password");
  CHECK(got.words == 0, "payload zeroed on failure");
  /* one word changed: checksum catches it before the KDF */
  memcpy(pw, v->pw, sizeof(pw));
  int typo_caught = 0, typos = 0;
  for (uint16_t w = 0; w < 2048; w += 97) {
    if (w == v->pw[5]) continue;
    pw[5] = w;
    typos++;
    wl_status_t st = wl_backup_open(v->file, sizeof(v->file), pw, work, sizeof(work), &got);
    CHECK(st == WL_ERR_CHECKSUM || st == WL_ERR_AUTH, "typo -> checksum or auth error");
    typo_caught += st == WL_ERR_CHECKSUM;
  }
  CHECK(typo_caught >= typos * 3 / 4, "most single-word typos caught by the checksum (%d of %d)", typo_caught, typos);
  pw[5] = 2048; /* not a word */
  CHECK(wl_backup_open(v->file, sizeof(v->file), pw, work, sizeof(work), &got) == WL_ERR_CHECKSUM, "index out of range");
}

static void test_tamper(void) {
  const backup_vec_t *v = &BACKUP_VECTORS[2];
  uint8_t f[WL_BACKUP_FILE_LEN];
  wl_backup_payload_t got;
  int damaged = 0, auth_or_format = 0;
  for (size_t byte = 0; byte < sizeof(f); byte++) {
    for (int bit = 0; bit < 8; bit += 3) {
      memcpy(f, v->file, sizeof(f));
      f[byte] ^= (uint8_t)(1u << bit);
      /* plain corruption: the checksum notices before any password work */
      wl_status_t st = wl_backup_open(f, sizeof(f), v->pw, work, sizeof(work), &got);
      CHECK(st == WL_ERR_DAMAGED || (byte < 8 && st == WL_ERR_FORMAT), "flip %zu.%d -> damaged (got %d)", byte, bit, st);
      damaged += st == WL_ERR_DAMAGED;
      /* deliberate tampering with the checksum recomputed: authentication must catch it */
      if (byte < 132) {
        fix_check(f);
        st = wl_backup_open(f, sizeof(f), v->pw, work, sizeof(work), &got);
        CHECK(st == WL_ERR_AUTH || st == WL_ERR_FORMAT || st == WL_ERR_ARG, "tamper %zu.%d rejected (got %d)", byte, bit, st);
        CHECK(got.words == 0, "nothing returned for tampered %zu.%d", byte, bit);
        auth_or_format += st != WL_OK;
      }
    }
  }
  CHECK(damaged > 0 && auth_or_format > 0, "tamper loop ran");
  /* the DEMO flag specifically: a demo backup cannot be passed off as a real one (and back) */
  memcpy(f, v->file, sizeof(f));
  f[9] ^= 1;
  fix_check(f);
  wl_backup_info_t info;
  CHECK(wl_backup_inspect(f, sizeof(f), &info) == WL_OK && info.demo != v->demo, "flag flip is well-formed");
  CHECK(wl_backup_open(f, sizeof(f), v->pw, work, sizeof(work), &got) == WL_ERR_AUTH, "flag flip fails authentication");
}

static void test_format(void) {
  const backup_vec_t *v = &BACKUP_VECTORS[2];
  uint8_t f[WL_BACKUP_FILE_LEN + 1];
  wl_backup_payload_t got;
  wl_backup_info_t info;
  CHECK(wl_backup_inspect(v->file, 139, &info) == WL_ERR_FORMAT, "truncated");
  memcpy(f, v->file, 140);
  f[140] = 0;
  CHECK(wl_backup_inspect(f, 141, &info) == WL_ERR_FORMAT, "too long");
  CHECK(wl_backup_inspect(NULL, 140, &info) == WL_ERR_FORMAT, "null");
  memcpy(f, "TREDDERX", 8);
  CHECK(wl_backup_inspect(f, 140, &info) == WL_ERR_FORMAT, "magic");
  /* hostile settings, checksum fixed so only the limits stop them */
  struct {
    size_t off;
    uint32_t val;
    wl_status_t want;
  } bad[] = {{16, 65, WL_ERR_FORMAT},       /* passes above the limit: would hang the device */
             {16, 0, WL_ERR_FORMAT},        /* zero passes */
             {12, 4, WL_ERR_FORMAT},        /* memory below the Argon2 minimum */
             {12, 1u << 20, WL_ERR_ARG}};   /* 1 GiB: more than this device has */
  for (size_t i = 0; i < NV(bad); i++) {
    memcpy(f, v->file, 140);
    for (int k = 0; k < 4; k++) f[bad[i].off + k] = (uint8_t)(bad[i].val >> (8 * k));
    fix_check(f);
    CHECK(wl_backup_open(f, 140, v->pw, work, sizeof(work), &got) == bad[i].want, "hostile setting %zu", i);
  }
  /* a smaller work area than the file needs */
  CHECK(wl_backup_open(BACKUP_VECTORS[0].file, 140, BACKUP_VECTORS[0].pw, work, 32 * 1024, &got) == WL_ERR_ARG,
        "not enough memory -> refused before any work");
  /* other versions / KDFs / lanes / lengths */
  size_t offs[] = {8, 10, 11, 48, 50};
  for (size_t i = 0; i < NV(offs); i++) {
    memcpy(f, v->file, 140);
    f[offs[i]] ^= 0x40;
    fix_check(f);
    CHECK(wl_backup_inspect(f, 140, &info) == WL_ERR_FORMAT, "unsupported field at %zu", offs[i]);
  }
}

/* Authentic files whose payload is invalid: built here with the same primitives. */
static void seal_raw(const uint8_t pt[64], const backup_vec_t *v, uint8_t f[140]) {
  memcpy(f, v->file, 52);
  uint8_t ent[16] = {0}, key[32];
  for (unsigned bit = 0; bit < 128; bit++)
    if (v->pw[bit / 11] >> (10 - bit % 11) & 1u) ent[bit / 8] |= (uint8_t)(0x80u >> (bit % 8));
  crypto_argon2_config c = {CRYPTO_ARGON2_ID, v->m_kib, v->passes, 1};
  crypto_argon2_inputs in = {ent, v->salt, 16, 16};
  crypto_argon2(key, 32, work, c, in, crypto_argon2_no_extras);
  chacha20poly1305_ctx x;
  rfc7539_init(&x, key, v->nonce);
  rfc7539_auth(&x, f, 52);
  chacha20poly1305_encrypt(&x, pt, f + 52, 64);
  rfc7539_finish(&x, 52, 64, f + 116);
  fix_check(f);
}

static void test_payload_validation(void) {
  const backup_vec_t *v = &BACKUP_VECTORS[2];
  uint8_t pt[64], f[140];
  wl_backup_payload_t got;
  /* sanity: the helper reproduces the real file */
  memset(pt, 0, sizeof(pt));
  pt[0] = 1, pt[1] = v->words, pt[2] = v->blind;
  for (int i = 0; i < v->words; i++) pt[4 + 2 * i] = (uint8_t)v->idx[i], pt[5 + 2 * i] = (uint8_t)(v->idx[i] >> 8);
  uint8_t good[64];
  memcpy(good, pt, 64);
  seal_raw(pt, v, f);
  CHECK(!memcmp(f, v->file, 140), "raw sealer matches");
  struct {
    size_t off;
    uint8_t val;
    const char *what;
  } bad[] = {{0, 2, "payload version"}, {1, 13, "word count 13"}, {1, 0, "word count 0"}, {1, 25, "word count 25"},
             {2, 0x80, "unknown flag"},  {3, 1, "reserved byte"}, {60, 1, "padding"},   {4 + 2 * 12, 1, "unused index"},
             {5, 0x08, "index >= 2048"}, {0, 0, "seed checksum"}};
  for (size_t i = 0; i < NV(bad); i++) {
    memcpy(pt, good, 64);
    if (i == NV(bad) - 1) pt[4 + 2 * (v->words - 1)] ^= 1; /* last word's low bits are checksum bits */
    else pt[bad[i].off] = bad[i].val;
    seal_raw(pt, v, f);
    CHECK(wl_backup_open(f, 140, v->pw, work, sizeof(work), &got) == WL_ERR_FORMAT && got.words == 0,
          "authentic but invalid payload refused: %s", bad[i].what);
  }
}

static void test_seal_args(void) {
  const backup_vec_t *v = &BACKUP_VECTORS[2];
  wl_backup_payload_t p = payload_of(v);
  wl_kdf_t kdf = {8, 1};
  uint8_t f[140];
  p.words = 13;
  CHECK(wl_backup_seal(&p, v->pw, false, kdf, v->salt, v->nonce, work, sizeof(work), f) == WL_ERR_ARG, "13 words");
  p = payload_of(v);
  p.idx[p.words - 1] ^= 1; /* checksum bits */
  CHECK(wl_backup_seal(&p, v->pw, false, kdf, v->salt, v->nonce, work, sizeof(work), f) == WL_ERR_ARG, "bad seed");
  p = payload_of(v);
  uint16_t pw[12];
  memcpy(pw, v->pw, sizeof(pw));
  pw[11] ^= 1;
  CHECK(wl_backup_seal(&p, pw, false, kdf, v->salt, v->nonce, work, sizeof(work), f) == WL_ERR_CHECKSUM, "bad password");
  wl_kdf_t big = {128, 1};
  CHECK(wl_backup_seal(&p, v->pw, false, big, v->salt, v->nonce, work, sizeof(work), f) == WL_ERR_ARG, "kdf too big");
}

void test_backup(int *checks, int *fails) {
  g_checks_p = checks, g_fail_p = fails;
  test_argon2_rfc9106();
  test_vectors();
  test_passwords();
  test_tamper();
  test_format();
  test_payload_validation();
  test_seal_args();
}
